import 'package:flutter/material.dart';
enum TopDestination{introduction,workers,humans}
class TopNavigation extends StatelessWidget{final TopDestination selected;final ValueChanged<TopDestination>onSelected;const TopNavigation({super.key,required this.selected,required this.onSelected});@override Widget build(BuildContext c)=>NavigationRail(extended:MediaQuery.sizeOf(c).width>=1050,selectedIndex:selected.index,onDestinationSelected:(i)=>onSelected(TopDestination.values[i]),destinations:const[NavigationRailDestination(icon:Icon(Icons.menu_book_outlined),label:Text('Introduction')),NavigationRailDestination(icon:Icon(Icons.spa_outlined),label:Text('Criterivox Workers / Bloom')),NavigationRailDestination(icon:Icon(Icons.person_outline),label:Text('Human Civilians / Profile'))]);}
